import React from 'react';
import { useTranslation } from '@getvim/translate';
import { defineMessages } from 'react-intl';
import Text from '../text';
import { AlignEnum, SizeEnum } from '../../types';
import img911 from './911.png';
import es from './translations/es.json';
import './index.less';

const messages = defineMessages({
  emergencyText: {
    defaultMessage: 'If you are having a medical emergency, <strong>please dial 911.</strong>',
    id: 'atoms.emergencyBanner.emergencyText',
  },
});

export default function EmergencyBanner() {
  const intl = useTranslation({ es } as any);

  return (
    <div className="emergency-banner">
      <div className="emergency-icon">
        <img src={img911} width={20} alt="emergency" />
      </div>
      <Text
        size={SizeEnum['12px']}
        align={AlignEnum.left}
        className="emergency-text"
        text={intl.formatMessage(messages.emergencyText, {
          strong: (chunks) => `<strong>${chunks}</strong>`,
        })}
        html
      />
    </div>
  );
}
